Looking at the request, I need to:

1. Add an "AI View" button to LogViewer.vue
2. Create a new component `LogAIView.vue` that creates a quick chat in task mode
3. When logs are refreshed, add them to the chat and call `chatWithProject` for analysis

Let me first check how `chatWithProject` works and the chat store structure.

```vue client/src/components/LogAIView.vue
<script setup>
import ChatView from './chat/ChatView.vue'
</script>

<template>
  <div class="w-full h-full flex flex-col gap-2">
    <div v-if="!aiChat" class="flex items-center justify-center h-full">
      <button class="btn btn-primary" @click="initAIChat">
        <i class="fa-solid fa-robot mr-2"></i>
        Start AI Log Analysis
      </button>
    </div>
    <div v-else class="w-full h-full flex flex-col">
      <div class="flex items-center gap-2 px-2 py-1 bg-base-200 rounded">
        <i class="fa-solid fa-robot text-primary"></i>
        <span class="text-sm font-semibold">AI Log Analysis</span>
        <div class="grow"></div>
        <button class="btn btn-xs btn-ghost" @click="analyzeNewLogs" :disabled="analyzing">
          <i :class="['fa-solid', analyzing ? 'fa-spinner animate-spin' : 'fa-magnifying-glass']"></i>
          <span class="ml-1">Analyze logs</span>
        </button>
      </div>
      <div class="grow overflow-hidden">
        <ChatView :chat="aiChat" class="h-full" />
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    logs: {
      type: Array,
      default: () => []
    }
  },
  data() {
    return {
      aiChat: null,
      analyzing: false,
      lastAnalyzedLogCount: 0
    }
  },
  computed: {
    activeProject() {
      return this.$storex.projects.activeProject
    },
    newLogs() {
      return this.logs.slice(this.lastAnalyzedLogCount)
    }
  },
  watch: {
    // Auto-analyze when new logs arrive if chat already initialized
    logs(newVal) {
      if (this.aiChat && newVal.length > this.lastAnalyzedLogCount) {
        this.analyzeNewLogs()
      }
    }
  },
  methods: {
    async initAIChat() {
      // Create a temporary task-mode chat for log analysis
      this.aiChat = await this.$storex.chats.createNewChat({
        name: 'Log Analysis',
        mode: 'task',
        temp: true,
        project_id: this.activeProject?.id,
        owner_project_id: this.activeProject?.id,
        profiles: [],
        messages: []
      })
      await this.analyzeNewLogs()
    },
    async analyzeNewLogs() {
      if (!this.aiChat || this.analyzing || !this.logs.length) return
      this.analyzing = true
      try {
        const logsToAnalyze = this.newLogs.length ? this.newLogs : this.logs.slice(-100)
        const logContent = logsToAnalyze.join('\n')
        const userMessage = {
          role: 'user',
          content: `Please analyze the following application logs and provide insights on errors, warnings, and overall health:\n\`\`\`\n${logContent}\n\`\`\``,
          done: false
        }
        this.lastAnalyzedLogCount = this.logs.length
        // Add message to chat and trigger AI response
        await this.activeProject.$api.chats.chatWithProject({
          ...this.aiChat,
          messages: [...(this.aiChat.messages || []), userMessage]
        })
        // Reload chat to get updated messages
        await this.$storex.chats.reloadChat(this.aiChat)
        this.aiChat = this.$storex.chats.allChats.find(c => c.id === this.aiChat.id) || this.aiChat
      } catch (err) {
        console.error('AI log analysis error:', err)
      } finally {
        this.analyzing = false
      }
    }
  },
  beforeUnmount() {
    // Clean up temp chat on unmount
    if (this.aiChat?.temp) {
      this.$storex.chats.deleteChat(this.aiChat)
    }
  }
}
</script>
```

Now update the `LogViewer.vue` to include the AI View toggle:

```vue client/src/components/LogViewer.vue
<script setup>
import RequestMetrics from './metrics/RequestMetrics.vue'
import LogAIView from './LogAIView.vue'
</script>

<template>
  <div class="px-2 pt-4 gap-2 w-full overflow-auto flex flex-col h-full relative">
    <header class="flex flex-row justify-between items-center">
      <h1 class="text-xl font-semibold">Dashboard</h1>
      <div class="flex gap-2 items-center">
        <button class="btn btn-sm" @click="clearLogs">
          <i class="fa-solid fa-trash-can"></i>
        </button>
        <button class="btn btn-sm" @click="fetchLogs">
          <i class="fa-solid fa-rotate"></i>
        </button>
        <label class="flex items-center space-x-2">
          <input type="checkbox" @click="toggleAutoRefresh" :cheked="$storex.logs.autoRefresh" class="checkbox checkbox-xs" />
          <span>Auto-refresh</span>
        </label>
        <label class="flex items-center space-x-2">
          <input type="checkbox" @click="follow = !follow" :cheked="follow" class="checkbox checkbox-xs" />
          <span>Follow</span>
        </label>
        <div class="grow"></div>
        <div>
          <input class="input input-xs w-10" v-model="tailSize" />
        </div>
        <div class="px-2">({{ $storex.logs.filteredLogs.length }})</div>
        <!-- AI View toggle button -->
        <button
          :class="['btn btn-sm', showAIView ? 'btn-primary' : 'btn-ghost']"
          @click="toggleAIView"
          title="AI Log Analysis"
        >
          <i class="fa-solid fa-robot"></i>
          <span class="ml-1">AI View</span>
        </button>
      </div>
    </header>

    <!-- AI View panel -->
    <div v-if="showAIView" class="grow overflow-hidden">
      <LogAIView :logs="rawLogs" />
    </div>

    <!-- Normal log view -->
    <template v-else>
      <div class="grid grid-cols-4 gap-1 my-2">
        <div 
          v-for="module in visibleModules" 
          :key="module" 
          @click="toggleModuleVisible(module)"
          :style="{ color: $ui.colorsMap[module] }"
          :class="['click badge badge-sm', logModules[module]?.visible ? 'border border-white': 'badge-outline']"
        >
          {{ module }}
        </div>
        <div 
          v-for="module in profilerModuleFilter" 
          :key="module" 
          @click="toggleProfilerVisible(module)"
          :style="{ color: $ui.colorsMap[module] }"
          :class="['click badge badge-sm', logModules[module]?.visible ? 'border border-white': 'badge-outline']"
        >
          {{ module }}
        </div>
      </div>
      <div class="grow overflow-auto flex flex-col">
        <div class="p-2" v-if="showMetrics">
          <RequestMetrics :title="'Requests'" :subtitle="'Requests path'"
            @filter-module="toggleProfilerVisible"
            :logs="requestLogs" class="mb-6" />
          <RequestMetrics :title="'Profiler'" :subtitle="'Method'"
            @filter-module="toggleProfilerVisible"
            :logs="profilerLogs" class="mb-6" />
        </div>
        <select @change="onLogChange" class="select select-sm rounded w-1/3">
          <option :selected="log === $storex.logs.selectedLog" 
            v-for="log in $storex.logs.logNames" :key="log" :value="log">{{ log }}</option>
        </select>
        <header class="flex flex-row justify-between items-center mt-2">
          <div class="flex gap-1 items-center">
            <input class="input input-xs input-bordered" placeholder="CSV patterns to discard"
              v-model="discardPatterns" />
            <label class="input input-xs input-bordered flex items-center gap-2">
              <input type="text" class="grow" placeholder="Search" v-model="filter" @keydown.enter="setNextMatchVisible" />
              <span v-if="filter">{{ matchCount }}</span>
              <span class="click" @click="clearFilter" v-if="filter"><i class="fa-regular fa-circle-xmark"></i></span>
              <span @click="applyFilter" v-else>
                <i class="fa-solid fa-magnifying-glass"></i>
              </span>
              <span class="click" @click="ignorePattern">
                <i class="fa-regular fa-eye-slash"></i>
              </span>
            </label>
          </div>
          <div class="grow"></div>
        </header>
        <div class="grow my-2 overflow-auto"
          style="height:600px" ref="logView">
          <div class="mb-2 text-wrap" 
            :class="[]"
            v-for="log, ix in filteredLogs" :key="`${log}-${ix}`"
            :ref="log.includes('log-match') ? 'match': null" v-html="log"></div>
          <div class="text-primary animate-pulse w-full">
            ...
          </div>
        </div>
      </div>
    </template>
  </div>
</template>

<script>
export default {
  data() {
    return {
      showAIView: false,
      showMetrics: false,
      showTimeFilter: false,
      logs: [],
      discardPatterns: '',
      logModules: {},
      visibleModules: [],
      profilerModuleFilter: [],
      tailSize: 250,
      filter: null,
      logLevelColors: {
        "INFO": "text-success",
        "DEBUG": "text-blue-600",
        "ERROR": "text-error",
        "WARNING": "text-warning"
      },
      timeSelection: null,
      follow: false,
      matchElements: []
    }
  },
  computed: {
    rawLogs() {
      return this.$storex.logs.rawLogs || []
    },
    requestLogs() {
      return this.logs.filter(log => log.data?.request)
                      .map(({ timestamp, data: { request: { url, time_taken } } }) => ({ timestamp, path: new URL(url).pathname, time_taken }))
    },
    profilerLogs() {
      return this.$storex.logs.filteredLogs.filter(log => log.data?.profiler)
                      .map(({ timestamp, data: { profiler: { module, method, time_taken } } }) => 
                                            ({ timestamp, path: `${module}.${method}`, time_taken }))
    },
    filteredLogs() {
      const discards = this.discardPatterns?.toLowerCase().split(",")
      const filters = this.filter?.split(",").filter(f => f.trim() !== "")

      return this.$storex.logs.rawLogs
        ?.filter(log => !discards?.length || !discards.find(d => log.toLowerCase().includes(d)))
        .map(l => l.includes('[ERROR]') ? `<span class="text-error">${l}</span>` : l)
        .map(log => {
          if (!filters?.length) return log
          let highlightedLog = log
          filters.forEach(f => {
            const regex = new RegExp(`(${f.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi')
            highlightedLog = highlightedLog.replace(regex, '<span class="log-match badge badge-sm badge-info badge-outline">$1</span>')
          })
          return highlightedLog
        })
    },
    matchCount() {
      return this.matchElements?.length
    }
  },
  watch: {
    filteredLogs() {
      if (this.follow) {
        const { logView } = this.$refs
        requestAnimationFrame(() => logView.scrollTo(0, logView.scrollHeight))
      }
      setTimeout(() => this.listMatchElements(), 500)
    }
  },
  methods: {
    toggleAIView() {
      this.showAIView = !this.showAIView
    },
    listMatchElements() {
      this.matchElements = [...this.$el.querySelectorAll('.log-match')]
      this.matchElements[0]?.scrollIntoView()
      this.currentSelectMatch = 0 
    },
    setNextMatchVisible() {
      this.currentSelectMatch = this.currentSelectMatch + 1
      if (this.currentSelectMatch >= this.matchElements.length) {
        this.currentSelectMatch = 0
      }
      this.matchElements[this.currentSelectMatch]?.scrollIntoView()
    },
    toggleModuleVisible(module) {
      const ix = this.visibleModules.indexOf(module)
      if (ix !== -1) {
        this.visibleModules.splice(ix, 1)
      } else {
        this.visibleModules.push(module)
      }
    },
    toggleTimeFilter() {
      this.showTimeFilter = !this.showTimeFilter
    },
    async fetchLogNames() {
      try {
        await this.$storex.logs.fetchLogNames()
        this.fetchLogs()
      } catch (error) {
        console.error('Error fetching log names:', error)
      }
    },
    async fetchLogs() {
      await this.$storex.logs.fetchLogs(this.tailSize)
    },
    toggleAutoRefresh() {
      this.$storex.logs.setAutoRefresh(!this.$storex.logs.autoRefresh)
      this.fetchLogs()
    },
    clearLogs() {
      this.$storex.logs.clearLogs()
    },
    onLogChange(ev) {
      this.$storex.logs.setSelectedLog(ev.target.value)
      this.clearLogs()
      this.fetchLogs()
    },
    scrollToBottom() {
      const { logView } = this.$refs
      if (logView) {
        logView.scrollTop = logView.scrollHeight
      }
      this.$el.scrollTop = this.$el.scrollHeight
    },
    logClasses(log) {
      const classes = []
      if (this.filter && this.isFilterMatch(log)) {
        classes.push("text-success")
      }
      if (log.toLocaleLowerCase().includes("error")) {
        classes.push("text-error")
      }
      return classes
    },
    isFilterMatch(log) {
      if (!this.filter) return true
      const lowerLog = log.toLowerCase()
      return this.filter.toLowerCase().split(",").find(e => lowerLog.includes(e))
    },
    ignorePattern() {
      this.$projects.addLogIgnore(this.filter?.toLowerCase())
      this.filter = null
    },
    applyFilter() {},
    clearFilter() {
      this.filter = null
      this.applyFilter()
    },
    toggleProfilerVisible(module) {
      if (this.profilerModuleFilter.includes(module)) {
        this.profilerModuleFilter.splice(this.profilerModuleFilter.indexOf(module), 1)
      } else {
        this.profilerModuleFilter.push(module)
      }
    }
  },
  mounted() {
    this.fetchLogNames()
  },
  beforeUnmount() {
    this.$storex.logs.setAutoRefresh(false)
  }
}
</script>
```

Key changes:
- **`LogViewer.vue`**: Added `showAIView` toggle button in the header, conditionally renders `<LogAIView>` or the normal log view using `v-if/v-else` with `<template>`. Also exposed `rawLogs` as a computed property passed as prop.
- **`LogAIView.vue`**: New component that creates a temporary `task`-mode chat via `createNewChat`, sends logs to `chatWithProject` for AI analysis, renders the chat using `ChatView`, and auto-analyzes when new logs arrive. Cleans up the temp chat on unmount.
